ALTER TABLE users ADD COLUMN IF NOT EXISTS access_role TEXT NOT NULL DEFAULT 'EMPLOYEE';
UPDATE users SET access_role=CASE WHEN role='ADMIN' THEN 'OWNER' WHEN can_manage_accounting THEN 'ACCOUNTANT' ELSE COALESCE(NULLIF(access_role,''),'EMPLOYEE') END;
CREATE TABLE IF NOT EXISTS user_permissions(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,permission_key TEXT NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,PRIMARY KEY(user_id,permission_key));
CREATE TABLE IF NOT EXISTS organization_settings(organization_id TEXT PRIMARY KEY REFERENCES organizations(id) ON DELETE CASCADE,system_name TEXT NOT NULL DEFAULT 'StockFlow',timezone TEXT NOT NULL DEFAULT 'Africa/Cairo',currency TEXT NOT NULL DEFAULT 'EGP',language TEXT NOT NULL DEFAULT 'ar',allocation_strategy TEXT NOT NULL DEFAULT 'FIFO',low_stock_threshold INTEGER NOT NULL DEFAULT 5,session_timeout_minutes INTEGER NOT NULL DEFAULT 480,allow_shared_accounts BOOLEAN NOT NULL DEFAULT TRUE,notifications_enabled BOOLEAN NOT NULL DEFAULT TRUE,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
INSERT INTO organization_settings(organization_id) SELECT id FROM organizations ON CONFLICT(organization_id) DO NOTHING;
